"""Decimal-aligned text and LaTeX tables built from FNumber cells."""

from __future__ import annotations

from collections.abc import Iterable, Sequence
from dataclasses import dataclass, field
from enum import Enum
from typing import Any

from text_format_table.config import DEFAULT_CONFIG, FormatConfig
from text_format_table.exceptions import (
    ColumnCountMismatchError,
    EmptyTableError,
    InvalidSignificantFiguresError,
)
from text_format_table.fnumber import Cell, FNumber

LATEX_HEADER_TEMPLATE = r"""
%%%% Table generated by formatTable utility %%%%
%%%% add \usepackage[group-separator={,}]{siunitx}
%%%%
\begin{table}
\begin{tabular}{%s}
\hline
"""

LATEX_HEADER_RULE = "\\hline\n"

LATEX_FOOTER = r"""\hline
\end{tabular}
\end{table}
%% Table generated by formatTable utility %%
"""

LATEX_COLUMN_SEPARATOR = " & "
LATEX_LINE_END = " \\\\\n"
TEXT_COLUMN_SEPARATOR = " | "
TEXT_LINE_END = " \n"
TEXT_RULE_CHAR = "-"
TEXT_FOOTER = "\n\n"


class OutputFormat(Enum):
    """Supported table output formats."""

    TEXT = "text"
    LATEX = "latex"


@dataclass(frozen=True)
class TableStyle:
    """Strings that frame a rendered table.

    Attributes:
        header: Emitted before the first row and after every page break.
        column_separator: Placed between cells.
        header_rule: Emitted after the header row.
        line_end: Terminates every row.
        footer: Emitted at every page break and at the end.
    """

    header: str
    column_separator: str
    header_rule: str
    line_end: str
    footer: str

    @classmethod
    def latex(cls, column_count: int) -> TableStyle:
        """Build the siunitx LaTeX style.

        Args:
            column_count: Number of S columns in the tabular spec.

        Returns:
            The LaTeX table style.
        """
        return cls(
            header=LATEX_HEADER_TEMPLATE % ("|" + "S|" * column_count),
            column_separator=LATEX_COLUMN_SEPARATOR,
            header_rule=LATEX_HEADER_RULE,
            line_end=LATEX_LINE_END,
            footer=LATEX_FOOTER,
        )

    @classmethod
    def text(cls, table_width: int) -> TableStyle:
        """Build the plain text style.

        Args:
            table_width: Width of the full table, used for the header rule.

        Returns:
            The text table style.
        """
        return cls(
            header="",
            column_separator=TEXT_COLUMN_SEPARATOR,
            header_rule=TEXT_RULE_CHAR * table_width + TEXT_LINE_END,
            line_end=TEXT_LINE_END,
            footer=TEXT_FOOTER,
        )


@dataclass
class ColumnOffsets:
    """Per-column alignment offsets.

    Simple container for column alignment offset information. Update with
    each number in the column and this object will return the column width and
    decimal offset required to accommodate all the numbers.

    Attributes:
        left: Per-column maximum offset (count up to the decimal point).
        right: Per-column maximum width to the right of the offset.
    """

    left: list[int] = field(default_factory=list)
    right: list[int] = field(default_factory=list)

    def update(self, column: int, left: int, right: int) -> None:
        """Widen column so it can hold a value with the given offsets.

        Args:
            column: Zero-based column index.
            left: The value's offset.
            right: The value's right offset.
        """
        while column >= len(self.left):
            self.left.append(0)
            self.right.append(0)
        self.left[column] = max(self.left[column], left)
        self.right[column] = max(self.right[column], right)

    def width(self, column: int) -> int:
        """Return the total width of column."""
        return self.left[column] + self.right[column]


def parse_sig_fig_list(text: str) -> list[int]:
    """Parse a per-column significant figure list such as ``"[1,2,2,4]"``.

    Brackets/parentheses are optional. Replaces the original ``exec`` so the
    CLI argument can never run code.

    Args:
        text: Comma separated integers, optionally in [] or ().

    Returns:
        The significant figures per column.

    Raises:
        InvalidSignificantFiguresError: If the list is empty or any entry is
            not an integer.
    """
    body = text.strip()
    if body[:1] + body[-1:] in ("[]", "()"):
        body = body[1:-1]
    items = [item.strip() for item in body.split(",")]
    if items and items[-1] == "":  # allow a trailing comma
        items.pop()
    try:
        sig_figs = [int(item) for item in items]
    except ValueError as error:
        raise InvalidSignificantFiguresError(
            f"significant figures by column must be a list of integers, got {text!r}"
        ) from error
    if not sig_figs:
        raise InvalidSignificantFiguresError("significant figures by column must not be empty")
    return sig_figs


class FormatTable:
    """Create a text table of decimal aligned numbers formatted with FNumber.

    The first row is treated as the header row: it is followed by a rule and
    repeated after every ``config.rows_per_page`` rows.

    Significant figures come from, in order of precedence:
        1. ``sf``: one value for the whole table,
        2. ``sflist``: one value per column,
        3. otherwise every cell is a ``(value, sig_figs)`` tuple.

    Attributes:
        output_format: TEXT or LATEX.
        cells: Rows of formatted cells.
        offsets: Per-column alignment offsets.
        style: Header/separator/footer strings for output_format.
    """

    def __init__(
        self,
        table: Iterable[Sequence[Any]],
        sf: int | str | None = None,
        latex: bool = False,
        sflist: str | Sequence[int] | None = None,
        max_col_width: int | None = None,
        config: FormatConfig = DEFAULT_CONFIG,
    ) -> None:
        """Format every cell of table and measure the columns.

        Args:
            table: Rows of values, or rows of (value, sig_figs) tuples when
                neither sf nor sflist is given.
            sf: Significant figures for every cell.
            latex: Produce a siunitx LaTeX table instead of a text table.
            sflist: Significant figures per column, as a list or a string such
                as ``"[1,2,2,4]"``.
            max_col_width: Maximum width of text cells, None for no limit.
            config: Separators and paging settings.

        Raises:
            EmptyTableError: If table has no rows.
            ColumnCountMismatchError: If a row is longer than sflist.
            InvalidSignificantFiguresError: If sf/sflist cannot be parsed or a
                numeric cell gets a non-positive count.
        """
        self.config = config
        self.output_format = OutputFormat.LATEX if latex else OutputFormat.TEXT
        self.max_col_width = max_col_width
        self.sig_figs = None if sf is None else _to_int(sf)
        self.column_sig_figs = parse_sig_fig_list(sflist) if isinstance(sflist, str) else sflist
        self.offsets = ColumnOffsets()
        self.cells = [self._build_row(row) for row in table]
        if not self.cells:
            raise EmptyTableError("cannot format a table with no rows")
        for row in self.cells:
            for column, cell in enumerate(row):
                self.offsets.update(column, cell.offset, cell.right_offset)
        self.style = self._build_style()

    def _split_row(self, row: Sequence[Any]) -> tuple[list[Cell], list[int]]:
        """Separate a row into its values and their significant figures.

        Args:
            row: One input row.

        Returns:
            Tuple of (values, significant figures), one per cell.

        Raises:
            ColumnCountMismatchError: If row is longer than the sflist.
        """
        if self.sig_figs is not None:
            # All numbers in the table use the same sf
            return list(row), [self.sig_figs] * len(row)
        if self.column_sig_figs is not None:
            if len(row) > len(self.column_sig_figs):
                raise ColumnCountMismatchError(
                    f"row has {len(row)} columns but only {len(self.column_sig_figs)} "
                    f"significant figure values were given: {list(row)!r}"
                )
            return list(row), [_to_int(s) for s in self.column_sig_figs[: len(row)]]
        # if sf=None, then each number is a tuple with the second element
        # containing the sf to use for that number
        return [value for value, _ in row], [_to_int(s) for _, s in row]

    def _build_row(self, row: Sequence[Any]) -> list[FNumber]:
        """Format every cell of row.

        Args:
            row: One input row.

        Returns:
            The formatted cells.
        """
        values, sig_figs = self._split_row(row)
        return [
            FNumber(value, sf, self.is_latex, self.max_col_width, self.config.number)
            for value, sf in zip(values, sig_figs, strict=True)
        ]

    @property
    def is_latex(self) -> bool:
        """True when rendering LaTeX."""
        return self.output_format is OutputFormat.LATEX

    def _build_style(self) -> TableStyle:
        """Return the style for output_format, sized to the first row."""
        if self.is_latex:
            return TableStyle.latex(len(self.cells[0]))
        # get full table width
        return TableStyle.text(len(self._render_row(self.cells[0], TEXT_COLUMN_SEPARATOR)))

    def _render_row(self, row: Sequence[FNumber], separator: str) -> str:
        """Pad and join the cells of row (without the line end).

        Args:
            row: Formatted cells.
            separator: Text placed between cells.

        Returns:
            The rendered row.
        """
        return separator.join(
            cell.pad(self.offsets.width(column), self.offsets.left[column])
            for column, cell in enumerate(row)
        )

    def render(self) -> str:
        """Render the full table, repeating the header every rows_per_page rows.

        Returns:
            The table text.
        """
        style = self.style
        parts = [style.header]
        header_line = ""
        for count, row in enumerate(self.cells, start=1):
            line = self._render_row(row, style.column_separator) + style.line_end
            parts.append(line)
            if count == 1:
                header_line = line
                parts.append(style.header_rule)
            if count % self.config.rows_per_page == 0:
                parts += [style.footer, style.header, header_line, style.header_rule]
        parts.append(style.footer)
        return "".join(parts)

    def __str__(self) -> str:
        """Return the rendered table."""
        return self.render()

    def __repr__(self) -> str:
        """Return a debugging representation."""
        return (
            f"<FormatTable rows={len(self.cells)} columns={len(self.offsets.left)} "
            f"format={self.output_format.value}>"
        )


def _to_int(sig_figs: Any) -> int:
    """Convert a significant figure value to int.

    Args:
        sig_figs: An int or a numeric string.

    Returns:
        The integer value.

    Raises:
        InvalidSignificantFiguresError: If the value is not an integer.
    """
    try:
        return int(sig_figs)
    except (TypeError, ValueError) as error:
        raise InvalidSignificantFiguresError(
            f"significant figures must be an integer, got {sig_figs!r}"
        ) from error
